import{_ as i,o as r,c as t,a2 as e}from"./chunks/framework.BqNd1sPY.js";const p=JSON.parse('{"title":"D12：对齐、强化学习与评测","description":"","frontmatter":{},"headers":[],"relativePath":"01-14天理论课/D12-对齐、强化学习与评测.md","filePath":"01-14天理论课/D12-对齐、强化学习与评测.md"}'),l={name:"01-14天理论课/D12-对齐、强化学习与评测.md"};function o(s,a,n,d,h,m){return r(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="d12-对齐、强化学习与评测" tabindex="-1">D12：对齐、强化学习与评测 <a class="header-anchor" href="#d12-对齐、强化学习与评测" aria-label="Permalink to &quot;D12：对齐、强化学习与评测&quot;">​</a></h1><h2 id="今日目标" tabindex="-1">今日目标 <a class="header-anchor" href="#今日目标" aria-label="Permalink to &quot;今日目标&quot;">​</a></h2><p>理解 <a href="/LLMTrain/05-速查表/术语速查#term-sft" class="wiki-term" data-wiki-title="SFT" data-wiki-summary="用输入与理想输出示例进行监督训练，使模型更符合目标行为。" data-wiki-misconception="SFT 会自动完成事实核验。">SFT</a> 之后为什么还会做偏好优化，以及如何用独立评测避免“只优化分数”。</p><h2 id="对齐在解决什么" tabindex="-1">对齐在解决什么 <a class="header-anchor" href="#对齐在解决什么" aria-label="Permalink to &quot;对齐在解决什么&quot;">​</a></h2><p><a href="/LLMTrain/05-速查表/术语速查#term-pretraining" class="wiki-term" data-wiki-title="pretraining" data-wiki-summary="在大规模数据上学习通用模式的基础训练阶段。" data-wiki-misconception="预训练数据越多，模型回答就必然越真实。">预训练</a>模型擅长续写，不自动等于有帮助、遵循指令或符合安全要求。后训练用示范、偏好比较、可验证奖励和安全数据塑造行为。</p><h3 id="rlhf-的典型高层流程" tabindex="-1">RLHF 的典型高层流程 <a class="header-anchor" href="#rlhf-的典型高层流程" aria-label="Permalink to &quot;RLHF 的典型高层流程&quot;">​</a></h3><ol><li><a href="/LLMTrain/05-速查表/术语速查#term-sft" class="wiki-term" data-wiki-title="SFT" data-wiki-summary="用输入与理想输出示例进行监督训练，使模型更符合目标行为。" data-wiki-misconception="SFT 会自动完成事实核验。">SFT</a> 得到能按指令回答的模型。</li><li>收集人类对多个回答的偏好。</li><li>训练奖励模型近似偏好。</li><li>用强化学习优化策略，同时常用参考模型约束偏离程度。</li></ol><p>这是典型流程，不是唯一实现，也不保证“对齐了所有人类价值”。</p><h3 id="dpo-与-grpo" tabindex="-1">DPO 与 GRPO <a class="header-anchor" href="#dpo-与-grpo" aria-label="Permalink to &quot;DPO 与 GRPO&quot;">​</a></h3><ul><li><strong><a href="/LLMTrain/05-速查表/术语速查#term-dpo" class="wiki-term" data-wiki-title="DPO" data-wiki-summary="直接利用偏好样本对优化策略，使偏好答案相对更可能。" data-wiki-misconception="DPO 不包含任何偏好目标或参考约束。">DPO</a></strong> 直接利用偏好对优化策略目标，避免显式训练并在线使用单独奖励模型的完整 <a href="/LLMTrain/05-速查表/术语速查#term-rlhf" class="wiki-term" data-wiki-title="RLHF" data-wiki-summary="利用人类偏好信号和强化学习优化模型行为的一类流程。" data-wiki-misconception="所有对齐都只能通过 RLHF 完成。">RLHF</a> 流程。</li><li><strong>GRPO</strong> 是一类基于同组多个输出相对奖励来估计优势的策略优化方法。它常见于可验证任务和<a href="/LLMTrain/05-速查表/术语速查#term-inference" class="wiki-term" data-wiki-title="inference" data-wiki-summary="使用训练好的参数，根据输入计算预测或生成结果。" data-wiki-misconception="推理阶段通常会继续更新模型权重。">推理</a>训练讨论，但不是对所有任务普遍优于其他方法的定律。</li></ul><p>算法名称不能替代奖励和数据设计。奖励有漏洞时，模型可能学会投机，即 reward hacking。</p><h2 id="评测金字塔" tabindex="-1">评测金字塔 <a class="header-anchor" href="#评测金字塔" aria-label="Permalink to &quot;评测金字塔&quot;">​</a></h2><ol><li><strong>训练和验证 <a href="/LLMTrain/05-速查表/术语速查#term-loss" class="wiki-term" data-wiki-title="loss" data-wiki-summary="训练目标对应的误差标量，优化器尝试让它下降。" data-wiki-misconception="一个 loss 数值足以代表模型的全部质量。">loss</a></strong>：检查学习与泛化趋势。</li><li><strong>任务指标</strong>：准确率、F1、pass@k、人工规则等。</li><li><strong>固定行为集</strong>：关键提示、边界情况、拒答与格式。</li><li><strong>人工评测</strong>：依据明确量表比较可用性。</li><li><strong>线上监测</strong>：真实分布、延迟、成本和事故。</li></ol><p>LLM-as-a-Judge 可扩展评测，但可能受位置、措辞、长度、模型家族和自我偏好影响，应随机交换顺序、隐藏模型身份、校准人工样本并报告不确定性。</p><h2 id="评测四条纪律" tabindex="-1">评测四条纪律 <a class="header-anchor" href="#评测四条纪律" aria-label="Permalink to &quot;评测四条纪律&quot;">​</a></h2><ul><li>训练集、开发集、测试集职责分离。</li><li>比较模型时统一提示、解码<a href="/LLMTrain/05-速查表/术语速查#term-parameter" class="wiki-term" data-wiki-title="parameter" data-wiki-summary="模型中由训练确定的数字；训练时只有未冻结的参数会被更新。" data-wiki-misconception="一个参数对应一条可直接读取的事实。">参数</a>和预算。</li><li>报告样本数、均值之外的波动或置信区间。</li><li>防止测试数据污染训练数据；旧 Benchmark 高分不自动代表真实新任务。</li></ul><h2 id="安全不是一项总分" tabindex="-1">安全不是一项总分 <a class="header-anchor" href="#安全不是一项总分" aria-label="Permalink to &quot;安全不是一项总分&quot;">​</a></h2><p>分别测试隐私泄露、提示注入、有害指导、偏见、越权工具调用和不可逆操作。一个平均分会掩盖低频高损害问题。</p><h2 id="今日验收" tabindex="-1">今日验收 <a class="header-anchor" href="#今日验收" aria-label="Permalink to &quot;今日验收&quot;">​</a></h2><p>设计 10 条客服评测：至少包含 3 条正常任务、2 条缺信息、2 条越权请求、2 条事实需引用、1 条对抗提示。说明每条的合格标准，而不只写“回答好”。</p><p>来源：<a href="https://arxiv.org/abs/2203.02155" target="_blank" rel="noreferrer">InstructGPT</a>、<a href="https://arxiv.org/abs/2305.18290" target="_blank" rel="noreferrer">DPO</a>、<a href="https://arxiv.org/abs/2402.03300" target="_blank" rel="noreferrer">DeepSeekMath</a></p><p>下一课：<a href="./D13-推理、部署、RAG与Agent">D13：推理、部署、RAG 与 Agent</a></p>',22)])])}const k=i(l,[["render",o]]);export{p as __pageData,k as default};
